function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // sky
  brush.fillBleed(1);
  brush.circle(0, 0, 300);
  brush.fillBleed(0.5);
  brush.beginShape(curvature);
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(200, 350);
  brush.endShape(true);
  // hills
  brush.fillBleed(1);
  brush.circle(200, 200, 50);
  brush.fillBleed(1);
  brush.circle(100, 100, 50);
  brush.fillBleed(0.5);
  brush.beginShape(curvature);
  brush.vertex(100, 100);
  brush.vertex(200, 200);
  brush.vertex(300, 100);
  brush.endShape(true);
  // details
  brush.fillBleed(0.5);
  brush.circle(200, 200, 30);
  brush.fillBleed(0.5);
  brush.circle(250, 150, 10);
}
